contract InvMutTest {
    C c;

    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address to, uint256 amount) public {
        require(to != address(0), "recipient is zero");

        uint256 senderBalanceBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 recipientBalanceBefore = c.balanceOf(to); if (__ESBMC_reverted()) return;
        uint256 totalSupplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        bool senderFrozenBefore = c.frozenAccount(address(this)); if (__ESBMC_reverted()) return;
        bool recipientFrozenBefore = c.frozenAccount(to); if (__ESBMC_reverted()) return;

        require(senderBalanceBefore >= amount, "insufficient balance");
        require(recipientBalanceBefore + amount >= recipientBalanceBefore, "overflow");
        require(!senderFrozenBefore, "sender frozen");
        require(!recipientFrozenBefore, "recipient frozen");

        bool success = c.transfer(to, amount); if (__ESBMC_reverted()) return;

        uint256 senderBalanceAfter = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 recipientBalanceAfter = c.balanceOf(to); if (__ESBMC_reverted()) return;
        uint256 totalSupplyAfter = c.totalSupply(); if (__ESBMC_reverted()) return;

        assert(success && senderBalanceAfter == senderBalanceBefore - amount && recipientBalanceAfter == recipientBalanceBefore + amount && totalSupplyAfter == totalSupplyBefore);
    }
}

